class CheckAromatherapyState(py_trees.behaviour.Behaviour):
    def __init__(self, name, state_url):
        super().__init__(name)
        self.state_url = state_url

    def update(self):
        try:
            response = http_client.get(self.state_url)
            if response.status_code == 200:
                state = response.json()
                if state == "on":
                    return Status.SUCCESS
                else:
                    return Status.FAILURE
            return Status.FAILURE
        except Exception:
            return Status.FAILURE


class TurnOnAromatherapy(py_trees.behaviour.Behaviour):
    def __init__(self, name, action_url):
        super().__init__(name)
        self.action_url = action_url

    def update(self):
        try:
            response = http_client.post(self.action_url)
            if response.status_code == 200:
                return Status.SUCCESS
            return Status.FAILURE
        except Exception:
            return Status.FAILURE


class SetAromatherapyInterval(py_trees.behaviour.Behaviour):
    def __init__(self, name, action_url, interval):
        super().__init__(name)
        self.action_url = action_url
        self.interval = interval

    def update(self):
        try:
            response = http_client.post(self.action_url, json={"interval": self.interval})
            if response.status_code == 200:
                return Status.SUCCESS
            return Status.FAILURE
        except Exception:
            return Status.FAILURE


# Create the behavior tree
check_state = CheckAromatherapyState(
    name="Check Aromatherapy State",
    state_url="http://localhost:8080/workspaces/home96/living_room/artifacts/livingRoomAromatherapy/properties/state"
)

turn_on = TurnOnAromatherapy(
    name="Turn On Aromatherapy",
    action_url="http://localhost:8080/workspaces/home96/living_room/artifacts/livingRoomAromatherapy/turn_on"
)

set_interval = SetAromatherapyInterval(
    name="Set Aromatherapy Interval",
    action_url="http://localhost:8080/workspaces/home96/living_room/artifacts/livingRoomAromatherapy/set_interval",
    interval=50
)

turn_on_sequence = py_trees.composites.Sequence(
    name="Turn On Sequence",
    memory=True,
    children=[check_state, turn_on]
)

root = py_trees.composites.Sequence(
    name="Root Sequence",
    memory=True,
    children=[turn_on_sequence, set_interval]
)

tree = root
